const webhookBody = $('cash-session/close').first().json.body; 
const sessionData = $('Get Session with Openings').first().json;
const movementsData = $('Get Movements Summary').all().map(item => item.json);

const sessionId = sessionData.id;
const closingNotes = webhookBody.notes || '';
const closingDetails = webhookBody.closing_denominations || {};

// Saldos iniciales
const openingBalances = sessionData.opening_balances || [];
const currenciesToProcess = ['UYU', 'USD']; 

const outputArray = [];

for (const currency of currenciesToProcess) {

    // A. DATOS DE APERTURA (Solo Físico)
    const openingObj = openingBalances.find(b => b.currency === currency);
    const openingAmount = parseFloat(openingObj ? openingObj.opening_amount : 0);

    // B. DATOS DE MOVIMIENTOS (Sistema)
    const movs = movementsData.find(m => m.currency === currency) || { 
        cash_in: 0, cash_out: 0, card_total: 0, transfer_total: 0, other_total: 0 
    };

    const sysCashIn = parseFloat(movs.cash_in || 0);
    const sysCashOut = parseFloat(movs.cash_out || 0);
    const sysCard = parseFloat(movs.card_total || 0);
    const sysTransfer = parseFloat(movs.transfer_total || 0);
    const sysOther = parseFloat(movs.other_total || 0);

    // C. DATOS DECLARADOS (Usuario cuenta billetes)
    const declaredKey = `declared_cash_${currency.toLowerCase()}`;
    const declaredPhysicalCash = parseFloat(webhookBody[declaredKey] || 0);

    // PASO 1: Calcular saldo físico esperado
    const expectedPhysicalBalance = (openingAmount + sysCashIn) - sysCashOut;

    // PASO 2: Calcular EXPECTATIVA GLOBAL DEL SISTEMA (Cuánto valor generó/tiene la sesión)
    const totalSystemExpectation = openingAmount;

    // PASO 3: Calcular TOTAL DE ACTIVOS REALES (Lo que declaramos tener)
    const totalAssetsDeclared = declaredPhysicalCash + sysCard + sysTransfer + sysOther;

    // PASO 4: VARIACIÓN
    const variance = totalAssetsDeclared - totalSystemExpectation;
    const cash_variance = declaredPhysicalCash - expectedPhysicalBalance;

    // -----------------------------------------------------------------------

    outputArray.push({
        json: {
            cash_session_id: sessionId,
            currency: currency,

            // Guardamos el declarado físico
            declared_cash: declaredPhysicalCash,

            // Guardamos el calculado físico (para referencia futura del saldo de caja)
            calculated_cash: expectedPhysicalBalance,

            // Guardamos los acumuladores digitales
            calculated_card: sysCard,
            calculated_transfer: sysTransfer,
            calculated_other: sysOther,
            total_cash_payouts: sysCashOut,

            // La varianza final del ejercicio
            cash_variance: cash_variance,

            // Extras
            closing_notes: closingNotes,
            closing_details: closingDetails 
        }
    });
}

return outputArray;

