// Función para extraer cotización USD
function extractUSDRate(htmlContent) {
  // El BROU usa una tabla con class que contiene las cotizaciones
  // Buscamos la fila de USD (Dólar USA)

  let compra = null;
  let venta = null;

  // Regex para encontrar la fila de USD y extraer compra/venta
  // El patrón busca: texto "USD" o "Dólar" seguido de valores numéricos
  const usdPattern = /(?:USD|D[óo]lar\s*(?:USA|Estadounidense|Americano)).*?([\d]+[,.]?[\d]*).*?([\d]+[,.]?[\d]*)/gis;

  // Alternativa: buscar en estructura de tabla
  // Patrón para tablas del BROU
  const tableRowPattern = /<tr[^>]*>.*?(?:USD|DOLAR|Dólar).*?<\/tr>/gis;
  const valuePattern = />\s*([\d]{2}[,.]\d{1,4})\s*</g;

  // Buscar filas que contengan USD
  const rows = htmlContent.match(tableRowPattern);

  if (rows && rows.length > 0) {
    for (const row of rows) {
      // Verificar que sea USD (no otra moneda)
      if (/USD|D[óo]lar\s*(USA|Estadounidense|Americano|Billete)?/i.test(row)) {
        const values = [];
        let match;

        // Extraer todos los valores numéricos de la fila
        const numPattern = />\s*([\d]{2}[,.]\d{1,4})\s*</g;
        while ((match = numPattern.exec(row)) !== null) {
          values.push(parseFloat(match[1].replace(',', '.')));
        }

        // Los dos primeros valores típicamente son compra y venta
        if (values.length >= 2) {
          // Compra es generalmente el menor, venta el mayor
          compra = Math.min(values[0], values[1]);
          venta = Math.max(values[0], values[1]);
          break;
        }
      }
    }
  }

  // Fallback: búsqueda más simple
  if (!compra || !venta) {
    const simplePattern = /USD[^\d]*([\d]{2}[,.]\d+)[^\d]*([\d]{2}[,.]\d+)/i;
    const simpleMatch = htmlContent.match(simplePattern);
    if (simpleMatch) {
      const v1 = parseFloat(simpleMatch[1].replace(',', '.'));
      const v2 = parseFloat(simpleMatch[2].replace(',', '.'));
      compra = Math.min(v1, v2);
      venta = Math.max(v1, v2);
    }
  }

  return { compra, venta };
}

