const item = $('cash-session/close').first();
const binaryData = item.binary;
const newItems = [];

for (const key in binaryData) {
    if (binaryData.hasOwnProperty(key) && binaryData[key]) {
        const fileObject = binaryData[key];

        const newItem = {
            json: {
                binaryPropertyName: key,
                fileName: fileObject.fileName,
                mimeType: fileObject.mimeType
            },
            binary: {
                data: fileObject
            }
        };

        newItems.push(newItem);
    }
}

return newItems;

return $input.all().map(item => {
  const closing = item.json.closing_details || {};
  const deposit = item.json.bank_deposit_details || {};
  const difference = {};

  // 1. Recorremos cada moneda (ej: 'uyu', 'usd') presente en el cierre
  for (const currency in closing) {
    difference[currency] = {};
    let newTotal = 0;

    // 2. Recorremos cada denominación (ej: '50', '2000') dentro de esa moneda
    for (const denom in closing[currency]) {
      // Saltamos la llave 'total' antigua porque la vamos a recalcular
      if (denom === 'total') continue;

      // Cantidad en cierre
      const closeQty = closing[currency][denom];

      // Cantidad depositada (si no existe la moneda o el billete en el depósito, es 0)
      const depQty = (deposit[currency] && deposit[currency][denom]) ? deposit[currency][denom] : 0;

      // Resta
      const diffQty = closeQty - depQty;

      // Guardamos la cantidad resultante en el objeto final
      difference[currency][denom] = diffQty;

      // 3. Recalculamos el total monetario
      // Multiplicamos la cantidad restante por el valor del billete (parseado a número)
      newTotal += diffQty * parseFloat(denom);
    }

    // Asignamos el nuevo total calculado
    difference[currency]['total'] = newTotal;
  }

  // Retornamos el item original agregando el campo 'difference_details'
  return {
    json: {
      ...item.json,
      difference_details: difference
    }
  };
});
